from taf.hw.pdu import pdu

from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class PduManager:
    def __init__(self, pdu_ip: str, pdu_model: str, pdu_version: str, device_alias: str = "alias") -> object:
        self.pdu_ip = pdu_ip
        self.pdu_model = pdu_model
        self.pdu_version = pdu_version
        self.device_alias = device_alias
        self.pdu_conn = None

    def __repr__(self):
        return f"PduManager(pdu_ip={self.pdu_ip!r}, pdu_model={self.pdu_model!r}, pdu_version={self.pdu_version!r}, " \
               f"device_alias={self.device_alias!r}, pdu_conn={self.pdu_conn!r})"

    def __str__(self):
        return f"Object of PduManager with pdu_ip '{self.pdu_ip}' and device_alias '{self.device_alias}'"

    def __enter__(self):
        self.connect()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.disconnect()

    def connect(self):
        self.pdu_conn = pdu()
        self.pdu_conn.setup_pdu(
            model=self.pdu_model, version=self.pdu_version, host=self.pdu_ip, alias=self.device_alias
        )
        test_logger(f"pdu {self.pdu_model} {self.pdu_ip}: connection was established", console=False)

    def disconnect(self):
        if self.pdu_conn:
            self.pdu_conn.teardown_pdu(pdu_device=self.device_alias)
        test_logger(f"pdu {self.pdu_model} {self.pdu_ip}: disconnected", console=False)

    def power_on(self, port_nr: int):
        self.pdu_conn.power_on(port_nr, self.device_alias)
        port_status = self.pdu_conn.get_port_status(port_nr, self.device_alias)
        test_logger(f"pdu {self.pdu_ip}; port {port_nr} -> {port_status}", console=False)

    def power_off(self, port_nr: int):
        self.pdu_conn.power_off(port_nr, self.device_alias)
        port_status = self.pdu_conn.get_port_status(port_nr, self.device_alias)
        test_logger(f"pdu {self.pdu_ip}; port {port_nr} -> {port_status}", console=False)
